/* Multiple-choice helper. A wrong answer never counts against the student: Bridge kindly explains
   why that choice doesn't fit (q.wrong[i]) and invites another try. */
function mountChoices(el,q,onCorrect){
 el.innerHTML='<p style="font-family:var(--font-head);font-size:1.3rem;color:var(--navy);margin:0 0 18px;line-height:1.4"></p><div></div><p class="feedback" aria-live="polite"></p>';
 el.querySelector('p').textContent=q.q;
 const box=el.querySelector('div'),fb=el.querySelector('.feedback');
 q.options.forEach((o,i)=>{const b=document.createElement('button');b.className='choice';b.textContent=o;
  b.onclick=()=>{
   if(i===q.answer){b.classList.add('right');box.querySelectorAll('button').forEach(x=>x.disabled=true);fb.className='feedback ok';fb.textContent='🎉 Yes! '+q.why;onCorrect()}
   else{b.classList.add('tryagain');b.disabled=true;fb.className='feedback retry';
    fb.textContent='Good try! 💡 '+((q.wrong&&q.wrong[i])||"That one doesn't fit this time.")+' Pick another one!'}};
  box.appendChild(b)});
}
