let _bid=0;
function badgeSVG(level,n,icon,size){
 const P={explorer:['#7FCB6E','#12864A','#0B5A31'],builder:['#7CCBF5','#159FE8','#0B6FAE'],communicator:['#4A86C5','#0B3B6B','#072645'],leader:['#FFE9A8','#F5C24D','#B9861B']}[level]||['#7FCB6E','#12864A','#0B5A31'];
 const id='bg'+(++_bid),cy={explorer:104,builder:114,communicator:98,leader:100}[level]||104;
 let shape='';
 if(level==='builder'){
  shape='<rect x="28" y="56" width="144" height="118" rx="24" fill="url(#'+id+')" stroke="#fff" stroke-width="6"/>'+
   [44,83,122].map(x=>'<rect x="'+x+'" y="34" width="34" height="28" rx="11" fill="url(#'+id+')" stroke="#fff" stroke-width="4"/>').join('')+
   [[48,76],[152,76],[48,154],[152,154]].map(c=>'<circle cx="'+c[0]+'" cy="'+c[1]+'" r="5" fill="'+P[2]+'"/>').join('');
 }else if(level==='communicator'){
  shape='<path d="M42 38H158Q182 38 182 62V136Q182 160 158 160H120L94 190L90 160H42Q18 160 18 136V62Q18 38 42 38Z" fill="url(#'+id+')" stroke="#fff" stroke-width="6" stroke-linejoin="round"/>'+
   '<circle cx="46" cy="52" r="4" fill="#fff" opacity=".7"/><circle cx="60" cy="52" r="4" fill="#fff" opacity=".5"/><circle cx="74" cy="52" r="4" fill="#fff" opacity=".3"/>';
 }else if(level==='leader'){
  shape='<path d="M100 14L176 40V100C176 148 140 176 100 194C60 176 24 148 24 100V40Z" fill="url(#'+id+')" stroke="#fff" stroke-width="6" stroke-linejoin="round"/>'+
   '<path d="M100 2l7 15 16 2-12 11 3 16-14-8-14 8 3-16-12-11 16-2z" fill="#fff" stroke="'+P[2]+'" stroke-width="2.5" stroke-linejoin="round"/>';
 }else{
  shape='<circle cx="100" cy="104" r="80" fill="url(#'+id+')" stroke="#fff" stroke-width="6"/>'+
   '<circle cx="100" cy="104" r="68" fill="none" stroke="#fff" stroke-width="2.5" stroke-dasharray="3 7" opacity=".85"/>'+
   '<path d="M100 27C88 6 64 8 60 26C78 32 92 32 100 27Z" fill="#7FCB6E" stroke="#fff" stroke-width="3.5" stroke-linejoin="round"/>'+
   '<path d="M100 27C112 6 136 8 140 26C122 32 108 32 100 27Z" fill="#12864A" stroke="#fff" stroke-width="3.5" stroke-linejoin="round"/>';
 }
 const spark=(x,y,d)=>'<path class="spark" style="animation-delay:'+d+'s" d="M'+x+' '+(y-9)+'L'+(x+3)+' '+(y-3)+'L'+(x+9)+' '+y+'L'+(x+3)+' '+(y+3)+'L'+x+' '+(y+9)+'L'+(x-3)+' '+(y+3)+'L'+(x-9)+' '+y+'L'+(x-3)+' '+(y-3)+'Z" fill="#FFE9A8" stroke="#fff" stroke-width="1.5"/>';
 return '<svg class="lbbadge" width="'+(size||150)+'" viewBox="0 0 200 210" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="'+level+' badge, lesson '+n+'">'+
  '<defs><linearGradient id="'+id+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="'+P[0]+'"/><stop offset="1" stop-color="'+P[1]+'"/></linearGradient></defs>'+
  shape+'<circle cx="100" cy="'+cy+'" r="42" fill="#fff"/><circle cx="100" cy="'+cy+'" r="42" fill="none" stroke="'+P[0]+'" stroke-width="3"/>'+
  '<text x="100" y="'+(cy+16)+'" text-anchor="middle" font-size="46">'+icon+'</text>'+
  '<rect x="44" y="170" width="112" height="28" rx="14" fill="'+P[2]+'" stroke="#fff" stroke-width="3"/>'+
  '<text x="100" y="189" text-anchor="middle" font-family="Lexend,sans-serif" font-size="13" font-weight="700" fill="#fff" letter-spacing=".5">LESSON '+n+'</text>'+
  spark(22,44,0)+spark(180,70,.7)+spark(170,20,1.3)+'</svg>';
}
